      grepNoMatch: "sin coincidencias para '{name}'",
      grepMatches: "{count} coincidencias en {files} archivos",
      manName: "NOMBRE",
      manSynopsis: "SINOPSIS",
      manDescription: "DESCRIPCIÓN",
      manExamples: "EJEMPLOS",
