      grepNoMatch: "no matches for '{name}'",
      grepMatches: "{count} matches in {files} files",
      manName: "NAME",
      manSynopsis: "SYNOPSIS",
      manDescription: "DESCRIPTION",
      manExamples: "EXAMPLES",
      soundNow: "sound {state}",
      soundCurrent: "sound is {state}",
      soundOn: "on",
