    sudo: {
      usage: "sudo hire",
      run(ctx) {
        const T = TerminalCommands;
        // hire is the only command allowed to run with elevated privileges.
        if (ctx.args[0]?.toLowerCase() === "hire") return T.registry.hire.run({ ...ctx, args: ctx.args.slice(1) });
        ctx.print(T.t("sudoDenied"), "err");
      },
