  usage: "scan [target]",
  run(ctx) {
    const T = TerminalCommands;
    const target = ctx.args[0] || "v1r3.dev";
    const steps = [
      { text: T.t("scanTarget", { target }), kind: "dim", wait: 200 },
      { text: T.t("scanStart"), kind: "dim", wait: 300 },
      { text: T.t("scanPorts"), kind: "default", wait: 400 },
      { text: T.t("scanSsl"), kind: "default", wait: 400 },
      { text: T.t("scanHeaders"), kind: "default", wait: 400 },
      { text: T.t("scanDeps"), kind: "default", wait: 400 },
      { text: T.t("scanFuzz"), kind: "default", wait: 400 },
      { text: T.t("scanDone"), kind: "accent", wait: 300 },
      { text: T.t("scanGrade"), kind: "accent", wait: 0 },
    ];
    ctx.play(steps);
  },
},

ai: {
  usage: "ai <question>",
  run(ctx) {
    const T = TerminalCommands;
    const q = ctx.args.join(" ").toLowerCase();
    if (!q) return ctx.print(T.t("aiUsage"), "err");
    if (q.includes("skill") || q.includes("tech")) {
      ctx.print(T.t("aiSkills"), "accent");
    } else if (q.includes("contact") || q.includes("hire") || q.includes("email")) {
      ctx.print(T.t("aiContact"), "accent");
    } else {
      ctx.print(T.t("aiDefault"), "accent");
    }
  },
},

"theme-editor": {
  usage: "theme-editor <hex>|reset",
  run(ctx) {
    const T = TerminalCommands;
    const arg = ctx.args[0];
    if (!arg) return ctx.print(T.t("themeEditorUsage"), "err");
    if (arg.toLowerCase() === "reset") {
      document.documentElement.style.removeProperty("--accent");
      return ctx.print(T.t("themeEditorReset"));
    }
    if (!/^#[0-9a-fA-F]{3,6}$/.test(arg)) return ctx.print(T.t("themeEditorInvalid", { arg }), "err");
    document.documentElement.style.setProperty("--accent", arg);
    ctx.print(T.t("themeEditorApplied", { color: arg }));
  },
},

