      helpHeader: "Comandos disponibles:",
      helpFooter: "Ejecuta 'help <comando>' para más detalles.",
      desc_help: "lista los comandos o muestra su uso",
      desc_ls: "lista el contenido de un directorio (-l detalles, -a archivos ocultos)",
