      themeEditorApplied: "Color de acento actualizado correctamente a {color}.",
      scanTarget: "[*] Objetivo: {target}",
      scanSsl: "[+] Certificado SSL/TLS: Válido (TLS 1.3, ECDSA)... SEGURO",
