    open: ["open contact/github.txt", "open experience"],
    theme: ["theme claude", "theme"],
    lang: ["lang en", "lang es"],
    grep: ["grep angular", "grep java ~/skills", "grep full-stack ~"],
    sound: ["sound off", "sound on"],
    sudo: ["sudo hire"],
