    neofetch: {
      usage: "neofetch",
      run(ctx) {
        const T = TerminalCommands;
        const rows = [
          ["Role", T.t("infoRole")],
          ["Focus", T.t("infoFocus")],
          ["Location", T.t("infoLocation")],
